package com.sumedha.commerce.user.entity; import jakarta.persistence.*; import java.time.*; import java.util.*;
@Entity @Table(name="user_preferences") public class UserPreference { @Id @Column(name="preference_id") private UUID id; @Column(name="profile_id",unique=true) private UUID profileId; private String language,currency; @Column(name="marketing_emails") private boolean marketingEmails; @Column(name="order_notifications") private boolean orderNotifications; @Column(name="created_at") private Instant createdAt; @Column(name="updated_at") private Instant updatedAt; protected UserPreference(){} public UserPreference(UUID p){id=UUID.randomUUID();profileId=p;language="en";currency="USD";orderNotifications=true;createdAt=Instant.now();updatedAt=createdAt;} @PreUpdate void touch(){updatedAt=Instant.now();} public UUID getProfileId(){return profileId;} public String getLanguage(){return language;} public String getCurrency(){return currency;} public boolean isMarketingEmails(){return marketingEmails;} public boolean isOrderNotifications(){return orderNotifications;} public void update(String l,String c,boolean m,boolean o){language=l;currency=c;marketingEmails=m;orderNotifications=o;} }
